		voxel_gi_free = T::voxel_gi_free;
		voxel_gi_initialize = T::voxel_gi_initialize;
		voxel_gi_allocate_data = T::voxel_gi_allocate_data;
		voxel_gi_get_bounds = T::voxel_gi_get_bounds;
